import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { toast } from '../libs/toast';
import {
  FaTachometerAlt, FaUsers, FaCalendarAlt, FaFileAlt,
  FaChartBar, FaCog, FaSignOutAlt, FaPlus, FaEye, FaEdit, FaTrash
} from 'react-icons/fa';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';
import './Dashboard.css';

const Dashboard: React.FC = () => {
  const { logout } = useAuth();
  const [stats, setStats] = useState({
    totalAnnouncements: 0,
    todayAnnouncements: 0,
    totalActors: 0,
    totalPrograms: 0
  });
  const [recentAnnouncements, setRecentAnnouncements] = useState([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState('');
  const [currentTime, setCurrentTime] = useState('');

  useEffect(() => {
    fetchDashboardData();
    // Live date/time
    const now = new Date();
    setCurrentDate(now.toLocaleDateString('fa-IR', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' }));
    setCurrentTime(now.toLocaleTimeString('fa-IR', { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
    const dateInterval = setInterval(() => {
      const d = new Date();
      setCurrentDate(d.toLocaleDateString('fa-IR', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' }));
    }, 60000);
    const timeInterval = setInterval(() => {
      const d = new Date();
      setCurrentTime(d.toLocaleTimeString('fa-IR', { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
    }, 1000);
    return () => {
      clearInterval(dateInterval);
      clearInterval(timeInterval);
    };
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.ctrlKey || e.altKey || e.metaKey) return;
      const k = e.key.toLowerCase();
      if (k === 'n') { window.location.href = '/announcements/new'; }
      if (k === 'a') { window.location.href = '/actors'; }
      if (k === 'p') { window.location.href = '/programs'; }
      if (k === 'd') { window.location.href = '/dashboard'; }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  const fetchDashboardData = async () => {
    try {
      const [announcementsRes, actorsRes, programsRes] = await Promise.all([
        axios.get('/api/announcements'),
        axios.get('/api/actors'),
        axios.get('/api/programs')
      ]);

      const announcements = announcementsRes.data;
      const today = new Date().toISOString().split('T')[0];
      const todayCount = announcements.filter((a: any) => a.date === today).length;

      setStats({
        totalAnnouncements: announcements.length,
        todayAnnouncements: todayCount,
        totalActors: actorsRes.data.length,
        totalPrograms: programsRes.data.length
      });

      setRecentAnnouncements(announcements.slice(0, 5));
    } catch (error) {
      toast.error('خطا در دریافت اطلاعات داشبورد');
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteAnnouncement = async (id: string) => {
  if (window.confirm('آیا از حذف این آفیش مطمئن هستید؟')) {
      try {
        await axios.delete(`/api/announcements/${id}`);
    toast.success('آفیش با موفقیت حذف شد');
        fetchDashboardData();
      } catch (error) {
    toast.error('خطا در حذف آفیش');
      }
    }
  };

  const menuItems = [
  { title: 'آفیش‌ها', icon: FaFileAlt, link: '/announcements', color: '#3498db' },
    { title: 'عوامل', icon: FaUsers, link: '/actors', color: '#2ecc71' },
    { title: 'برنامه‌ها', icon: FaCalendarAlt, link: '/programs', color: '#e74c3c' },
    { title: 'نمایش عمومی', icon: FaEye, link: '/display', color: '#9b59b6' },
  ];

  if (loading) {
    return (
      <div className="dashboard-loading">
        <div className="loading-spinner"></div>
        <p>در حال بارگذاری...</p>
      </div>
    );
  }

  return (
    <div className="dashboard-container">
      <div className="dashboard-header">
        <h1>داشبورد مدیریت</h1>
        <div className="header-actions">
          <div className="header-meta">
            <div className="current-date">{currentDate}</div>
            <div className="live-time">{currentTime}</div>
          </div>
          <button onClick={logout} className="btn btn-danger">
            <FaSignOutAlt />
            خروج
          </button>
        </div>
      </div>

      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon" style={{ backgroundColor: '#3498db' }}>
            <FaFileAlt />
          </div>
          <div className="stat-info">
            <h3>{stats.totalAnnouncements}</h3>
  <p>کل آفیش‌ها</p>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon" style={{ backgroundColor: '#2ecc71' }}>
            <FaCalendarAlt />
          </div>
          <div className="stat-info">
            <h3>{stats.todayAnnouncements}</h3>
  <p>آفیش‌های امروز</p>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon" style={{ backgroundColor: '#e74c3c' }}>
            <FaUsers />
          </div>
          <div className="stat-info">
            <h3>{stats.totalActors}</h3>
            <p>کل عوامل</p>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon" style={{ backgroundColor: '#f39c12' }}>
            <FaChartBar />
          </div>
          <div className="stat-info">
            <h3>{stats.totalPrograms}</h3>
            <p>کل برنامه‌ها</p>
          </div>
        </div>
      </div>

      <div className="dashboard-content">
        <div className="quick-actions">
          <h2>عملیات سریع</h2>
          <div className="action-grid">
            {menuItems.map((item, index) => (
              <Link key={index} to={item.link} className="action-card" style={{ borderColor: item.color }}>
                <div className="action-icon" style={{ color: item.color }}>
                  <item.icon />
                </div>
                <h3>{item.title}</h3>
              </Link>
            ))}
          </div>
        </div>

        <div className="recent-announcements">
          <div className="section-header">
  <h2>آخرین آفیش‌ها</h2>
            <Link to="/announcements/new" className="btn btn-success">
              <FaPlus />
  آفیش جدید
            </Link>
          </div>

          <div className="announcements-table">
            <table>
              <thead>
                <tr>
                  <th>عنوان</th>
                  <th>تاریخ</th>
                  <th>زمان</th>
                  <th>برنامه</th>
                  <th>عملیات</th>
                </tr>
              </thead>
              <tbody>
                {recentAnnouncements.length === 0 ? (
                  <tr>
  <td colSpan={5} className="empty-message">هیچ آفیشی یافت نشد</td>
                  </tr>
                ) : (
                  recentAnnouncements.map((announcement: any) => (
                    <tr key={announcement.id}>
                      <td>{announcement.title}</td>
                      <td>{announcement.date}</td>
                      <td>{announcement.time}</td>
                      <td>{announcement.program_title || '-'}</td>
                      <td className="actions">
                        <Link to={`/announcements/${announcement.id}`} className="action-btn view">
                          <FaEye />
                        </Link>
                        <Link to={`/announcements/${announcement.id}/edit`} className="action-btn edit">
                          <FaEdit />
                        </Link>
                        <button
                          onClick={() => handleDeleteAnnouncement(announcement.id)}
                          className="action-btn delete"
                        >
                          <FaTrash />
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
